{
  "ordinary_at_deadline": true,
  "correction_window": {
    "amount": 5,
    "unit": "minutes"
  },
  "correction_at_window_end": true,
  "correction_scope": "through_start",
  "reasons": {
    "R1": "일반 취소 마감은 이용 시작 24시간 전입니다. 이는 until_start_seconds >= 86400 (24시간)일 때 허용됩니다. 마감 시점은 포함됩니다.",
    "R2": "이용이 시작되면 일반 취소는 마감됩니다. until_start_seconds < 0 (이미 시작) 또는 0 (시작 시점)일 때는 취소를 거부합니다.",
    "R3": "방금 잘못 예약한 고객에게는 별도의 정정 시간이 있습니다. '방금'이라는 표현은 5분 이내의 짧은 기간을 의미하므로, age_seconds < 300 (5분)일 때는 취소를 허용합니다. 정정 기간은 이용 시작 전까지(through_start) 적용됩니다."
  }
}
